void HpaeGainNode::ResetFadeState()
{
    // A reused/reconnected GainNode may carry stale fade state from its previous lifecycle
    // (e.g. DONE_FADEOUT left by a Pause). DONE_FADEOUT makes SignalProcess silence every frame,
    // so it must be cleared; otherwise the reused node stays muted permanently.
    fadeOutState_ = FadeOutState::NO_FADEOUT;
    fadeInState_ = true; // fade-in on reconnect to avoid pop
    fadeProcessedBytes_ = 0;
    totalFadeBytes_ = 0;
    collFadeOutState_ = FadeOutState::NO_FADEOUT;
    collFadeInState_ = false;
    collFadeProcessedBytes_ = 0;
    collTotalFadeBytes_ = 0;
    AUDIO_INFO_LOG("ResetFadeState, session:%{public}u", GetSessionId());
}

std::shared_ptr<HpaeGainNode> sessionGainNode = sceneClusterMap_[sceneType]->GetGainNodeById(sessionId);
if (sessionGainNode != nullptr) {
    sessionGainNode->ResetVolume();
    sessionGainNode->ResetFadeState(); // clear stale fade (e.g. DONE_FADEOUT) on reconnect
}

auto gainNode = SafeGetMap(idGainMap_, sessionId);
if (!gainNode) {
    HpaeNodeInfo gainNodeInfo = preNodeInfo;
    idGainMap_[sessionId] = std::make_shared<HpaeGainNode>(gainNodeInfo);
} else {
    // Reuse existing node: clear stale fade state (e.g. DONE_FADEOUT left by a previous
    // Pause) so SignalProcess won't keep silencing data after the reconnect.
    gainNode->ResetFadeState();
    AUDIO_INFO_LOG("sessionId %{public}d gainNode already exist, reset fade state", sessionId);
}

// Stale DONE_FADEOUT silences every frame via SignalProcess (the bug).
hpaeGainNode->fadeOutState_ = FadeOutState::DONE_FADEOUT;
HpaePcmBuffer inputBuf(bufInfo);
FillBuffer(inputBuf, UT_UNIT_GAIN);
std::vector<HpaePcmBuffer *> inputs = {&inputBuf};
hpaeGainNode->SignalProcess(inputs);
EXPECT_EQ(inputBuf.GetPcmDataBuffer()[DEFAULT_FRAME_LEN * STEREO - 1], 0.0f); // silenced

} else {
    // Reuse existing node: clear stale fade state, mirroring HpaeProcessCluster::CreateGainNode.
    // (DisConnect erases the node, so reuse is unlikely, but reset for parity/defense.)
    gainNode->ResetFadeState();
    AUDIO_INFO_LOG("sessionId %{public}d gainNode already exist, reset fade state", sessionId);
}

hpaeGainNode->fadeOutState_ = FadeOutState::DONE_FADEOUT;
hpaeGainNode->collFadeOutState_ = FadeOutState::DONE_FADEOUT;
hpaeGainNode->fadeInState_ = false;
hpaeGainNode->collFadeInState_ = true;
hpaeGainNode->fadeProcessedBytes_ = 100;
hpaeGainNode->totalFadeBytes_ = 7680;
hpaeGainNode->collFadeProcessedBytes_ = 200;
hpaeGainNode->collTotalFadeBytes_ = 7680;

hpaeGainNode->ResetFadeState();

EXPECT_EQ(hpaeGainNode->fadeOutState_, FadeOutState::NO_FADEOUT);
EXPECT_EQ(hpaeGainNode->collFadeOutState_, FadeOutState::NO_FADEOUT);
EXPECT_EQ(hpaeGainNode->fadeInState_, true);
EXPECT_EQ(hpaeGainNode->collFadeInState_, false);
